{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatherapy Membership</title>
  <meta name="description" content="Membership-based aromatherapy support that may support daily calm, focus, and restful sleep. Safety-forward guidance, blends, and guided practices.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="index.html">{{BUSINESS_NAME}}</a>
      <nav class="primary-nav">
        <a href="services.html">Offerings</a>
        <a href="blends.html">Custom Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Plans</a>
        <a href="about.html">Our Approach</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
      <div class="header-actions">
        <a class="btn btn-ghost" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="hamburger" aria-label="menu" onclick="document.body.classList.toggle('nav-open')">☰</button>
      </div>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero">
      <div class="wrap hero-grid">
        <div class="hero-text">
          <h1>Thoughtful scent membership for steady daily care</h1>
          <p class="lede">Small, consistent scent practices that may support mood, sleep, and calm. Join a membership that combines seasonal blends, guided rituals, and safety-first coaching.</p>
          <p class="cta-row"><a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Begin your membership</a> <a class="btn btn-outline" href="book.html">Schedule a consult</a></p>
        </div>
        <div class="hero-panel" aria-hidden="false">
          <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
            <defs>
              <pattern id="p1" patternUnits="userSpaceOnUse" width="20" height="20">
                <rect width="20" height="20" fill="#fff" />
                <path d="M0 10 Q5 0 10 10 T20 10" stroke="#e6f3ee" stroke-width="1" fill="none" />
              </pattern>
            </defs>
            <rect width="200" height="200" fill="url(#p1)" />
          </svg>
          <div class="panel-content">
            <h3>Monthly ritual + blends</h3>
            <p>Each month members receive a seasonal blend, instructions for safe use, and a short guided practice you can do anywhere.</p>
            <ul class="feature-list">
              <li>Pre-diluted sample blends</li>
              <li>Patch test & pets guidance</li>
              <li>Access to member-only recordings</li>
            </ul>
          </div>
        </div>
      </div>
    </section>

    <!-- Framework (unique order) -->
    <section class="framework wrap" id="framework">
      <h2>Our simple support framework</h2>
      <div class="steps">
        <div class="step">
          <h4>Sense & Notice</h4>
          <p>Short prompts to check in with where scent can fit in your routine.</p>
        </div>
        <div class="step">
          <h4>Choose a Blend</h4>
          <p>Member blends are chosen for safety and gentle perceptual shifts; they may support focus or calm.</p>
        </div>
        <div class="step">
          <h4>Apply Safely</h4>
          <p>Clear dilution guidance, patch test reminders, and notes for pregnancy and pets.</p>
        </div>
      </div>
    </section>

    <!-- Story (different order) -->
    <section class="story wrap" id="story">
      <div class="story-grid">
        <div>
          <h2>Who we serve</h2>
          <p>People who want consistent, pragmatic aroma practices — without medical promises — that may support daily shifts in attention, sleep, and ease. We center safety and clarity so you can try scent with confidence.</p>
          <p class="muted">Local: {{CITY}}, {{STATE}} • Call: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div>
          <h3>Not a treatment — a sensory companion</h3>
          <p>Our plans emphasize safe dilution, transparent ingredient lists, and simple rituals that slot into your day. Membership gives you curated supplies plus guidance to use them responsibly.</p>
        </div>
      </div>
    </section>

    <!-- Offers -->
    <section class="offers wrap" id="offers">
      <h2>Memberships and services</h2>
      <div class="cards">
        <article class="card">
          <h3>Foundations Membership</h3>
          <p>Monthly blend, one guided audio practice, and member portal access.</p>
          <p class="price">Starting at <strong>$<span data-price-month="18">18</span>/mo</strong></p>
          <p><a class="btn btn-small" href="pricing.html">See plans</a></p>
        </article>
        <article class="card">
          <h3>Steady Support</h3>
          <p>Everything in Foundations plus a quarterly consult and shelf-stable kits.</p>
          <p class="price">Starting at <strong>$<span data-price-month="36">36</span>/mo</strong></p>
          <p><a class="btn btn-small" href="pricing.html">Compare</a></p>
        </article>
        <article class="card">
          <h3>Studio Custom</h3>
          <p>Custom blends for individual preferences, plus safety notes and usage plans.</p>
          <p class="price">From <strong>$<span data-price-month="120">120</span></strong></p>
          <p><a class="btn btn-small" href="blends.html">Start a consult</a></p>
        </article>
      </div>
    </section>

    <!-- Pricing Comparator (monthly vs package) -->
    <section class="pricing wrap" id="pricing">
      <h2>Plan comparison</h2>
      <div class="pricing-panel">
        <div class="toggle-row">
          <span class="label">Billing</span>
          <div class="toggle" role="switch" tabindex="0" aria-checked="true" id="billingToggle">
            <span class="toggle-knob"></span>
          </div>
          <span class="label" id="billingLabel">Monthly</span>
        </div>

        <div class="comparison">
          <div class="plan">
            <h4>Foundations</h4>
            <div class="amount">
              $<span class="animate-price" data-month="18" data-package="180">18</span>
              <small class="freq">/mo</small>
            </div>
            <p class="meta">Monthly blend, member audio</p>
            <a class="btn" href="{{PRIMARY_CTA_URL}}">Join Foundations</a>
          </div>
          <div class="plan">
            <h4>Steady Support</h4>
            <div class="amount">
              $<span class="animate-price" data-month="36" data-package="360">36</span>
              <small class="freq">/mo</small>
            </div>
            <p class="meta">Quarterly consults, kits</p>
            <a class="btn" href="{{PRIMARY_CTA_URL}}">Join Steady</a>
          </div>
          <div class="plan">
            <h4>Studio Custom</h4>
            <div class="amount">
              $<span class="animate-price" data-month="120" data-package="960">120</span>
              <small class="freq">/one-time</small>
            </div>
            <p class="meta">Custom blend + plan</p>
            <a class="btn" href="blends.html">Request a consult</a>
          </div>
        </div>
        <p class="pricing-note">All pricing shown as examples. Packages apply a small savings when billed up-front. No medical claims — may support general wellbeing. See FAQ for safety notes.</p>
      </div>
    </section>

    <!-- Proof Gallery: rotating testimonials + badges -->
    <section class="proof wrap" id="proof">
      <h2>Member feedback & credibility</h2>
      <div class="proof-grid">
        <div class="testimonials" id="testimonials">
          <blockquote class="quote" data-index="0">"I appreciate the clear dilution instructions—knowing what to do made introducing scent at home easy."<cite>— Mara, member</cite></blockquote>
          <blockquote class="quote" data-index="1">"The monthly audio practice became part of my evening routine. It's small but steady."<cite>— Jen, member</cite></blockquote>
          <blockquote class="quote" data-index="2">"Helpful notes about pets and patch testing. I felt informed and safe trying a new blend."<cite>— Ravi, member</cite></blockquote>
        </div>
        <div class="badges" id="badges">
          <div class="badge" data-tooltip="Family-safety guidance; dilution & pet notes included">Safe-use guidance</div>
          <div class="badge" data-tooltip="Ingredients listed with each blend; allergen notes provided">Transparent blends</div>
          <div class="badge" data-tooltip="Experienced aromatherapy practitioner; non-medical coaching">Practitioner-led</div>
        </div>
      </div>
      <div class="proof-controls">
        <button id="prevTestimonial" class="btn btn-small">Prev</button>
        <button id="nextTestimonial" class="btn btn-small">Next</button>
      </div>
    </section>

    <!-- FAQ / Safety -->
    <section class="faq wrap" id="faq">
      <h2>Safety & frequently asked</h2>
      <div class="qa">
        <details>
          <summary>Are these treatments?</summary>
          <div class="answer">We do not provide medical treatment. Aromatherapy practices and blends may support general wellbeing and daily routines but are not a substitute for medical care.</div>
        </details>
        <details>
          <summary>Patch test and dilution guidance</summary>
          <div class="answer">Every blend includes a dilution recommendation and a patch-test protocol. Start with a small amount and wait 24 hours to check for irritation.</div>
        </details>
        <details>
          <summary>Pregnancy, children, and pets</summary>
          <div class="answer">Some essential oils are not recommended during pregnancy or around young children and certain animals. We include clear notes and alternatives. Consult your healthcare provider for specific medical advice.</div>
        </details>
        <details>
          <summary>How to store blends</summary>
          <div class="answer">Store blends in a cool, dark place and label clearly. Keep out of reach of children and pets.</div>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta wrap" id="final-cta">
      <div class="cta-box">
        <h2>Ready to try a gentle scent practice?</h2>
        <p>Start with a one-month Foundations trial and get step-by-step safety guidance.</p>
        <p><a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">Start my trial</a> <a class="btn btn-outline" href="book.html">Book a consult</a></p>
      </div>
    </section>
  </main>

  <footer class="site-footer wrap">
    <div class="footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <div>
        <p>Phone: {{PHONE}}</p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <div>
        <nav class="footer-nav">
          <a href="privacy.html">Privacy</a>
          <a href="terms.html">Terms</a>
          <a href="contact.html">Contact</a>
        </nav>
      </div>
    </div>
    <small>© <span id="year"></span> {{BUSINESS_NAME}}</small>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
