{"path":"assets/css/styles.css","content":"/* Base styles */
:root{--bg:#fff;--muted:#6b6b6b;--accent:#6aa67a;--accent-2:#3a8d6b;--card:#fbfffc;--shadow:rgba(34,34,34,0.06)}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;margin:0;background:linear-gradient(180deg,#ffffff 0%,#f7fdf9 100%);color:#122;}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:transparent;padding:10px 0;position:sticky;top:0;backdrop-filter:blur(6px);z-index:20}
.site-header .wrap{display:flex;align-items:center;gap:12px}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none;font-size:1.15rem}
.primary-nav{margin-left:12px;display:flex;gap:10px}
.primary-nav a{color:#2b2b2b;text-decoration:none;padding:6px 8px;border-radius:6px}
.primary-nav a:hover{background:#f1fbf6}
.header-actions{margin-left:auto;display:flex;gap:8px;align-items:center}
.btn{display:inline-block;padding:8px 14px;border-radius:8px;text-decoration:none;color:#122;background:#fff;border:1px solid #e6eee6}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:var(--accent);color:#fff;border:none}
.btn-outline{background:transparent;border:1px solid var(--accent);color:var(--accent)}
.btn-small{padding:6px 10px;font-size:0.9rem}
.hamburger{display:none;border:0;background:transparent;font-size:1.25rem}
.hero{padding:40px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:20px;align-items:center}
.lede{color:var(--muted);margin-top:8px}
.hero-panel{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 20px var(--shadow);position:relative;overflow:hidden}
.hero-panel .pattern{position:absolute;right:-40px;top:-40px;width:220px;height:220px;opacity:0.8}
.panel-content{position:relative}
.feature-list{list-style:none;padding:0;margin:12px 0 0 0}
.feature-list li{padding:4px 0;color:var(--muted)}
.framework{padding:30px 0}
.steps{display:flex;gap:16px}
.step{background:#fff;padding:16px;border-radius:10px;flex:1;box-shadow:0 6px 18px rgba(20,60,40,0.03)}
.story{padding:30px 0}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.offers{padding:30px 0}
.cards{display:flex;gap:16px}
.card{flex:1;background:linear-gradient(180deg,#ffffff,#fbfffc);padding:18px;border-radius:12px;box-shadow:0 8px 24px rgba(15,40,20,0.03)}
.card h3{margin-top:0}
.price{font-size:1.05rem}
.pricing{padding:30px 0}
.pricing-panel{background:#f8fffa;padding:18px;border-radius:12px}
.toggle-row{display:flex;align-items:center;gap:12px;margin-bottom:12px}
.toggle{width:56px;height:28px;background:#eaf6ef;border-radius:20px;position:relative;cursor:pointer}
.toggle-knob{position:absolute;left:4px;top:4px;width:20px;height:20px;background:white;border-radius:50%;transition:transform .28s}
.toggle[aria-checked="false"] .toggle-knob{transform:translateX(28px)}
.comparison{display:flex;gap:12px}
.plan{flex:1;background:white;padding:12px;border-radius:10px}
.amount{font-size:1.4rem;font-weight:700}
.freq{font-size:0.9rem;color:var(--muted)}
.pricing-note{font-size:0.9rem;color:var(--muted);margin-top:10px}
.proof{padding:30px 0}
.proof-grid{display:grid;grid-template-columns:1fr 220px;gap:18px;align-items:start}
.testimonials{background:white;padding:18px;border-radius:12px;min-height:130px;box-shadow:0 8px 20px rgba(0,0,0,0.04);position:relative}
.quote{display:none;margin:0}
.quote.active{display:block}
.quote cite{display:block;margin-top:10px;color:var(--muted);font-style:normal}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:linear-gradient(180deg,#fff,#f6fff7);border:1px solid #e6f3eb;padding:10px;border-radius:8px;cursor:default;position:relative}
.badge:hover{background:#f0fff3}
.badge[data-tooltip]::after{content:attr(data-tooltip);position:absolute;left:calc(100% + 10px);top:50%;transform:translateY(-50%);background:#fff;border:1px solid #ddeedd;padding:8px;border-radius:6px;box-shadow:0 6px 18px rgba(10,40,20,0.06);white-space:nowrap;display:none}
.badge:hover[data-tooltip]::after{display:block}
.faq{padding:30px 0}
.qa details{background:#fff;padding:12px;border-radius:8px;margin-bottom:8px}
.cta{padding:30px 0}
.cta-box{background:linear-gradient(180deg,#ffffff,#f7fff5);padding:22px;border-radius:12px;text-align:center}
.site-footer{padding:24px 0;border-top:1px solid #eef7ee;margin-top:30px}
.footer-grid{display:flex;gap:20px;align-items:flex-start}
.muted{color:var(--muted)}
@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .story-grid{grid-template-columns:1fr}
  .cards{flex-direction:column}
  .comparison{flex-direction:column}
  .proof-grid{grid-template-columns:1fr}
  .primary-nav{display:none}
  .hamburger{display:block}
  .header-actions .btn-ghost{display:none}
}
/* small accessibility focus */
[tabindex]:focus{outline:3px solid #cfeede;outline-offset:3px}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Year in footer
  document.getElementById('year').textContent = new Date().getFullYear();

  // Pricing toggle
  var billingToggle = document.getElementById('billingToggle');
  var billingLabel = document.getElementById('billingLabel');
  var prices = document.querySelectorAll('.animate-price');
  var isMonthly = true;

  function animateValue(el, start, end, duration){
    var startTime = null;
    function step(ts){
      if(!startTime) startTime = ts;
      var progress = Math.min((ts - startTime) / duration, 1);
      var value = Math.round(start + (end - start) * progress);
      el.textContent = value;
      if(progress < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function updatePrices(monthly){
    prices.forEach(function(el){
      var m = parseFloat(el.getAttribute('data-month')) || 0;
      var p = parseFloat(el.getAttribute('data-package')) || 0;
      var from = parseFloat(el.textContent) || (monthly? p : m);
      var to = monthly? m : p;
      animateValue(el, from, to, 420);
      var freq = el.parentElement.querySelector('.freq');
      if(freq){
        freq.textContent = monthly ? '/mo' : (el.getAttribute('data-package') ? '/one-time' : '/package');
      }
    });
  }

  function setBilling(monthly){
    isMonthly = monthly;
    billingToggle.setAttribute('aria-checked', String(monthly));
    billingLabel.textContent = monthly ? 'Monthly' : 'Up-front package';
    updatePrices(monthly);
  }

  billingToggle.addEventListener('click', function(){ setBilling(!isMonthly); });
  billingToggle.addEventListener('keydown', function(e){ if(e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setBilling(!isMonthly); } });

  // Initialize prices
  setBilling(true);

  // Proof Gallery rotation
  var quotes = Array.prototype.slice.call(document.querySelectorAll('#testimonials .quote'));
  var idx = 0;
  function showQuote(i){
    quotes.forEach(function(q){ q.classList.remove('active'); });
    var q = quotes[i];
    if(q){ q.classList.add('active'); }
  }
  showQuote(0);
  var autoRotate = setInterval(function(){ idx = (idx + 1) % quotes.length; showQuote(idx); }, 6000);

  document.getElementById('prevTestimonial').addEventListener('click', function(){ clearInterval(autoRotate); idx = (idx - 1 + quotes.length) % quotes.length; showQuote(idx); });
  document.getElementById('nextTestimonial').addEventListener('click', function(){ clearInterval(autoRotate); idx = (idx + 1) % quotes.length; showQuote(idx); });

  // Simple tooltip activation for badges (for keyboard users)
  var badges = document.querySelectorAll('.badge');
  badges.forEach(function(b){
    b.setAttribute('tabindex', '0');
    b.addEventListener('focus', function(){ b.classList.add('focus'); });
    b.addEventListener('blur', function(){ b.classList.remove('focus'); });
  });

  // Small: reveal on scroll (progressive enhancement)
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){ if(entry.isIntersecting){ entry.target.classList.add('in-view'); } });
  }, {threshold:0.08});
  document.querySelectorAll('.step, .card, .plan, .quote').forEach(function(el){ io.observe(el); });

})();"} 
